// These isolated harness reloads test component rehydration, not the App-level F5 policy.
// Native refresh/close discard is qualified in preparation-tab-exit.spec.ts.
import {test,expect,type Page} from '@playwright/test';

test('combined email uses covered subsets and shows actual totals without Preview',async({page})=>{
 await readyCombined(page,false,false,true);
 await page.getByRole('button',{name:'Send now',exact:true}).click();
 await expect(page.getByRole('heading',{name:'Sending not confirmed',exact:true})).toBeVisible();
 await page.getByRole('button',{name:'Check shared status',exact:true}).click();
 await expect(page.getByRole('heading',{name:'Email sent',exact:true})).toBeVisible();
 await expect(page.locator('.email-send-result__counts')).toContainText('Invoices2');
 const proof=await page.evaluate(()=>JSON.parse(sessionStorage.getItem('combined-proof')!));
 expect(proof.sends).toBe(1);
 expect(proof.saved.members.find((m:any)=>m.accountId==='10').invoiceIds).toEqual(['102']);
 expect(proof.saved.totals.invoices).toBe(2);
});

async function pauseFirstAdmission(page:Page){await page.evaluate(()=>{const write=Storage.prototype.setItem;Storage.prototype.setItem=function(key,value){if(this===sessionStorage&&key.startsWith('ar-account-batch:')&&JSON.parse(value).combined?.attempted){Storage.prototype.setItem=write;throw new DOMException('Synthetic admission pause','QuotaExceededError');}return write.call(this,key,value);};});}

async function readyCombined(page:Page,exitProof=false,separate=false,removeInvoice=false){
 await page.goto('/tests/browser/batch-workspace/harness.html'+(exitProof?'?exit-proof=1':''));await page.getByRole('button',{name:'Collections',exact:true}).click();
 for(const [name,id] of [['Azure Travel','1001'],['Coral Travel','3001']]){await page.getByRole('button',{name:`Open KAT account ${name} · Synthetic`,exact:true}).click();await page.getByRole('checkbox',{name:`Queue select ${id}`,exact:true}).check();}
 if(removeInvoice){await page.getByRole('button',{name:'Open KAT account Azure Travel · Synthetic',exact:true}).click();await page.getByRole('checkbox',{name:'Queue select 1002',exact:true}).check();}
 await page.getByRole('button',{name:'Prepare documents',exact:true}).click();if(removeInvoice)await page.getByRole('combobox',{name:'Document content',exact:true}).selectOption('invoices');await page.getByRole('button',{name:'Prepare accounts',exact:true}).click();await expect(page.locator('.pdf-paper .pdf-canvas')).toHaveAttribute('data-render-state','ready');if(removeInvoice)await page.getByRole('button',{name:'Delete page',exact:true}).click();await page.locator('.batch-heading').getByRole('button',{name:'Go to email',exact:true}).click();await expect(page.getByRole('textbox',{name:'Email message',exact:true})).toBeVisible();if(separate)return;await combinedServer(page);await page.getByRole('radio',{name:'One combined email',exact:true}).click();
 await page.getByLabel('Common To',{exact:true}).fill('manual@example.invalid');await page.getByLabel('Common subject',{exact:true}).fill('One click reviewed message');await page.getByLabel('Common message',{exact:true}).fill('Reviewed common content');
}

test('one combined Send now click sends one exact message and replaces the composer',async({page})=>{
 await readyCombined(page);await page.evaluate(()=>{const previous=window.fetch.bind(window);window.fetch=async(input,init={})=>{const url=new URL(input instanceof Request?input.url:String(input),location.origin);if(url.pathname.endsWith('/send'))await new Promise<void>(resolve=>(window as any).releaseCombinedSend=resolve);return previous(input,init);};});
 await expect(page.getByRole('button',{name:'Send now',exact:true})).toHaveCount(1);await page.getByRole('button',{name:'Send now',exact:true}).click();await expect(page.getByRole('heading',{name:'Sending email…',exact:true})).toBeVisible();await expect(page.getByLabel('Common message',{exact:true})).toHaveCount(0);await expect(page.getByRole('button',{name:'Back to Collections',exact:true})).toBeDisabled();await page.evaluate(()=>(window as any).releaseCombinedSend());await expect(page.getByRole('heading',{name:'Sending not confirmed',exact:true})).toBeVisible();await page.getByRole('button',{name:'Check shared status',exact:true}).click();await expect(page.getByRole('heading',{name:'Email sent',exact:true})).toBeVisible();await expect(page.locator('.email-send-result__counts')).toContainText('Messages1Accounts2Invoices2Files2');expect(await page.evaluate(()=>JSON.parse(sessionStorage.getItem('combined-proof')!).sends)).toBe(1);
});

test('accepted combined result exits during a deferred history check without resurrecting resume',async({page})=>{
 await readyCombined(page);await page.getByRole('button',{name:'Send now',exact:true}).click();await expect(page.getByRole('heading',{name:'Sending not confirmed',exact:true})).toBeVisible();
 await page.evaluate(()=>{const previous=window.fetch.bind(window);window.fetch=async(input,init={})=>{const url=new URL(input instanceof Request?input.url:String(input),location.origin);if(url.pathname.endsWith('/deliveries/combined-proof/check'))await new Promise<void>(resolve=>(window as any).releaseCombinedCheck=resolve);return previous(input,init);};(window as any).batchCleanupOutcome='protected';(document.querySelector('#allow-confirm') as HTMLInputElement).checked=true;});
 await page.getByRole('button',{name:'Check shared status',exact:true}).click();await expect(page.getByRole('heading',{name:'Email sent',exact:true})).toBeVisible();await expect(page.getByText('History update pending',{exact:true}).first()).toBeVisible();await expect(page.getByRole('button',{name:'Back to Collections',exact:true})).toBeEnabled();await page.getByRole('button',{name:'Back to Collections',exact:true}).click();await expect(page.locator('.batch-heading')).toHaveCount(0);await page.evaluate(()=>(window as any).releaseCombinedCheck());await expect.poll(()=>page.evaluate(()=>Object.keys(sessionStorage).filter(k=>k.startsWith('ar-account-batch:')||k.startsWith('ar-account-batch-active:')))).toEqual([]);expect(await page.evaluate(()=>JSON.parse(sessionStorage.getItem('combined-proof')!).sends)).toBe(1);
});

test('combined original retry cannot send while batch exit cleanup is in flight',async({page})=>{
 await readyCombined(page);await page.evaluate(()=>{const previous=window.fetch.bind(window);(window as any).exitRetrySends=0;window.fetch=async(input,init={})=>{const url=new URL(input instanceof Request?input.url:String(input),location.origin);if(url.pathname.endsWith('/send')){(window as any).exitRetrySends++;return Response.json({error:'unauthorized'},{status:401});}if(url.pathname.endsWith('/abandon'))await new Promise<void>(resolve=>(window as any).releaseCombinedExit=resolve);return previous(input,init);};(document.querySelector('#allow-confirm') as HTMLInputElement).checked=true;});await page.getByRole('button',{name:'Send now',exact:true}).click();await expect(page.getByRole('heading',{name:'Sending not confirmed',exact:true})).toBeVisible();await page.getByRole('button',{name:'Check shared status',exact:true}).click();await expect(page.getByRole('button',{name:'Retry original send request',exact:true})).toBeEnabled();await page.locator('.batch-heading').getByRole('button',{name:'Collections',exact:true}).click();await expect.poll(()=>page.evaluate(()=>typeof (window as any).releaseCombinedExit)).toBe('function');await expect(page.getByRole('button',{name:'Retry original send request',exact:true})).toBeDisabled();expect(await page.evaluate(()=>(window as any).exitRetrySends)).toBe(1);
});

