 await page.getByLabel('Common To',{exact:true}).fill('manual@example.invalid');await page.getByLabel('Signature Hotel',{exact:true}).selectOption('TSK');await page.getByLabel('Common subject',{exact:true}).fill('Reviewed mixed package');await page.getByLabel('Common message',{exact:true}).fill('One message for all accounts.');await page.getByRole('button',{name:'Send now',exact:true}).click();

