async function largeSaveServer(page:Page){await page.evaluate(()=>{const previous=window.fetch.bind(window);window.fetch=async(input,init={})=>{const url=new URL(input instanceof Request?input.url:String(input),location.origin);if(url.pathname!=='/api/email/combined'||init.method!=='POST')return previous(input,init);const payload=String(init.body),body=JSON.parse(payload),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(payload)))).map(n=>n.toString(16).padStart(2,'0')).join(''),state=JSON.parse(sessionStorage.getItem('large-save-server')||'{"requests":[],"commands":{},"revision":0,"lost":false}');state.requests.push({commandId:body.commandId,revision:body.revision,hash,subject:body.content.subject});const persist=()=>sessionStorage.setItem('large-save-server',JSON.stringify(state)),prior=state.commands[body.commandId];if(prior){persist();if(prior.hash!==hash)return Response.json({error:'email_command_conflict'},{status:409});return Response.json(JSON.parse(sessionStorage.getItem('combined-proof')!).saved);}if(body.revision!==state.revision){persist();return Response.json({error:'email_revision_conflict'},{status:409});}const response=await previous(input,init),saved=await response.json() as {revision:number};state.revision=saved.revision;state.commands[body.commandId]={hash,revision:saved.revision};if(saved.revision===2&&!state.lost){state.lost=true;persist();throw new TypeError('Synthetic large save response lost');}persist();return Response.json(saved);};});}
