test('lost accepted response recovers through actual combined public GET and send replay before Back and close',async({page,context})=>{
 await readyCombined(page,true);
 await page.evaluate(()=>{const previous=window.fetch.bind(window);window.fetch=async(input,init={})=>{const p=new URL(input instanceof Request?input.url:String(input),location.href).pathname;
 if(p.endsWith('/abandon'))localStorage.setItem('final-public-exits',JSON.stringify([...JSON.parse(localStorage.getItem('final-public-exits')??'[]'),p]));
 const stored=()=>JSON.parse(sessionStorage.getItem('combined-proof')!);
 if(p.endsWith('/send')&&p.startsWith('/api/email/combined')){const state=stored();if(state?.sends)return Response.json((window as any).projectCombinedPublic(state.saved).delivery);try{return await previous(input,init);}catch(error){const accepted=stored();accepted.saved.delivery.preparationRetirement={accepted:true,privateProof:'must-not-leak'};sessionStorage.setItem('combined-proof',JSON.stringify(accepted));throw error;}}
 if(p.includes('/deliveries/combined-proof/check'))return Response.json((window as any).projectCombinedPublic(stored().saved).delivery);
 const response=await previous(input,init);if(/^\/api\/email\/combined\/[^/]+$/.test(p)&&(init.method??'GET')==='GET')return Response.json((window as any).projectCombinedPublic(await response.json()));return response;
 };});
 await page.getByRole('button',{name:'Send now',exact:true}).click();await expect(page.getByRole('heading',{name:'Sending not confirmed',exact:true})).toBeVisible();
 const replay=await page.evaluate(async()=>{const batch=JSON.parse(sessionStorage.getItem(Object.keys(sessionStorage).find(k=>k.startsWith('ar-account-batch:'))!)!),c=batch.combined;const r=await fetch('/api/email/combined/'+c.id+'/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:c.revision,commandId:c.sendCommandId,confirmed:true})});return r.json();});expect(replay).toMatchObject({state:'awaiting_evidence',recorded:false,gmailAccepted:true,preparationRetirement:{accepted:true}});expect(JSON.stringify(replay)).not.toContain('must-not-leak');
 await page.getByRole('button',{name:'Check shared status',exact:true}).click();await expect(page.getByRole('heading',{name:'Email sent',exact:true})).toBeVisible();await page.getByRole('button',{name:'Back to Collections',exact:true}).click();await expect.poll(()=>page.evaluate(()=>Object.keys(sessionStorage).filter(k=>k.startsWith('ar-account-batch:')).length)).toBe(0);expect(await page.evaluate(()=>JSON.parse(sessionStorage.getItem('combined-proof')!).sends)).toBe(1);expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('final-public-exits')??'[]'))).toEqual([]);
 const alive=await context.newPage();await alive.goto('/tests/browser/audit-email/harness.html');try{await page.close({runBeforeUnload:true});expect(await alive.evaluate(()=>Object.keys(localStorage).filter(k=>k.startsWith('ar-preparation-exit-v1:')))).toEqual([]);}finally{await alive.close();}
});
for(const kind of ['maintained','legacy'])test(`batch consumes ${kind} id-only terminal receipt with verified current job before Back`,async({page,context})=>{
 await readyCombined(page,true,true);
 await page.evaluate(kind=>{const previous=window.fetch.bind(window);(window as any).finalReceipts=[];window.fetch=async(input,init={})=>{const p=new URL(input instanceof Request?input.url:String(input),location.href).pathname,m=/^\/api\/documents\/([0-9a-f-]{36})\/abandon$/.exec(p);if(m){const db=JSON.parse(sessionStorage.getItem('ar-batch-fixture-server-v1')!),job=db.jobs[m[1]],original={job:{id:job.id},outcome:'protected',...kind==='maintained'?{preparationRetirement:{accepted:true}}:{}};(window as any).finalReceipts.push(original);return Response.json({...original,...kind==='maintained'?{currentJob:{...job,preparation_retirement:{accepted:true}}}:{}});}return previous(input,init);};},kind);
 await page.locator('.batch-heading').getByRole('button',{name:'Collections',exact:true}).click();await expect.poll(()=>page.evaluate(()=>Object.keys(sessionStorage).filter(k=>k.startsWith('ar-account-batch:')).length)).toBe(0);const receipts=await page.evaluate(()=>(window as any).finalReceipts);expect(receipts).toHaveLength(2);for(const receipt of receipts)expect(Object.keys(receipt.job)).toEqual(['id']);expect(await page.evaluate(()=>Object.keys(localStorage).filter(k=>k.startsWith('ar-preparation-exit-v1:')))).toEqual([]);
 const alive=await context.newPage();await alive.goto('/tests/browser/audit-email/harness.html');try{await page.close({runBeforeUnload:true});expect(await alive.evaluate(()=>Object.keys(localStorage).filter(k=>k.startsWith('ar-preparation-exit-v1:')))).toEqual([]);}finally{await alive.close();}
});
